        float4(halfWidth, halfHeight, -halfDepth, 1.0), 
        float4(halfWidth, halfHeight, halfDepth, 1.0), 
        float4(halfWidth, -halfHeight, -halfDepth, 1.0), 
        float4(halfWidth, -halfHeight, halfDepth, 1.0), 
        float4(halfWidth, halfHeight, halfDepth, 1.0), 
